CREATE TABLE IF NOT EXISTS {{prefix}}users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, display_name TEXT NOT NULL, created_at TEXT NOT NULL, last_login_at TEXT);
CREATE TABLE IF NOT EXISTS {{prefix}}demo_workspaces (id TEXT PRIMARY KEY, demo_date TEXT NOT NULL, is_template INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}patients (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, code TEXT NOT NULL, full_name TEXT NOT NULL, birth_date TEXT NOT NULL, UNIQUE(workspace_id, code));
CREATE TABLE IF NOT EXISTS {{prefix}}studies (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, patient_id INTEGER NOT NULL, study_uid TEXT NOT NULL, study_type TEXT NOT NULL, study_date TEXT NOT NULL, conclusion TEXT NOT NULL, UNIQUE(workspace_id, study_uid));
CREATE TABLE IF NOT EXISTS {{prefix}}facilities (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}services (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}specialists (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, full_name TEXT NOT NULL, service_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}routes (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, patient_id INTEGER NOT NULL, study_id INTEGER NOT NULL, status TEXT NOT NULL, assigned_to TEXT, attention_reason TEXT, due_date TEXT NOT NULL, return_reason TEXT, created_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS {{prefix}}route_steps (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, route_id INTEGER NOT NULL, sequence_no INTEGER NOT NULL, title TEXT NOT NULL, service_id INTEGER, status TEXT NOT NULL, required INTEGER NOT NULL DEFAULT 1, confirmation_required INTEGER NOT NULL DEFAULT 0, document_label TEXT, due_date TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS {{prefix}}schedule_slots (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, service_id INTEGER NOT NULL, specialist_id INTEGER NOT NULL, facility_id INTEGER NOT NULL, starts_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'free', UNIQUE(workspace_id, specialist_id, starts_at));
CREATE TABLE IF NOT EXISTS {{prefix}}appointments (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, route_step_id INTEGER NOT NULL, slot_id INTEGER NOT NULL, status TEXT NOT NULL, reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}comments (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, route_id INTEGER NOT NULL, body TEXT NOT NULL, author TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}event_log (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, route_id INTEGER, event_type TEXT NOT NULL, message TEXT NOT NULL, author TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}settings (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, setting_key TEXT NOT NULL, setting_value TEXT, UNIQUE(workspace_id, setting_key));
CREATE TABLE IF NOT EXISTS {{prefix}}action_keys (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, request_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id, request_key));
CREATE TABLE IF NOT EXISTS {{prefix}}login_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, identity TEXT NOT NULL, attempted_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS {{prefix}}migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS {{prefix}}idx_routes_workspace ON {{prefix}}routes(workspace_id, status, attention_reason);
CREATE INDEX IF NOT EXISTS {{prefix}}idx_slots_workspace ON {{prefix}}schedule_slots(workspace_id, starts_at, status);
CREATE INDEX IF NOT EXISTS {{prefix}}idx_events_workspace ON {{prefix}}event_log(workspace_id, created_at);
